P=[
("efbb09640bb3e324c223a4fa11adab6c8ed25d1a74160777c7bf21cf89f2e9b7","TITLE"),
("6059680b3fa0aa0c8179584bfc2117e8e008cec85e3e43a3db35ca8c6e03a737","Ek raat, ghane jungle mein, Bagheera ko ek tokri mili. Tokri mein ek nanha sa bacha tha. Woh akela tha, magar muskura raha tha. Bagheera ne socha, \"Is bache ko pyaar aur ghar chahiye.\""),
("d894b95a49d9d58ca02bf586debfe211918260327f66f70299df7f510e38fa1a","Bagheera bache ko bhediyon ke ghar le gaya. Ammi Bhediya ne bache ko pyaar se dekha. \"Aaj se yeh hamara beta hai,\" unhon ne kaha. Unhon ne uska naam rakha: Mowgli!"),
("a45961ecc25b4bea8b6b4e1ed26596bec43e64dcb93b42d94d26802a2f4b2e6f","Mowgli bhediyon ke bachon ke saath bada hua. Woh saath khelte, saath khaate, saath sote. Mowgli ke paas fur nahi tha, magar dil bilkul unke jaisa tha. Woh sab ek doosre ke bhai the."),
("c63348b465ddcee0873b77eb865198c261116b24bcb8cfa0d978c3e76d1ddb6d","Bagheera roz Mowgli ka khayal rakhta. Usne Mowgli ko darakht par chadhna sikhaya. Mowgli kai baar phisla, magar usne himmat nahi haari. \"Koshish karte raho,\" Bagheera ne kaha."),
("8a2710ce3868a2edc491dce34e5bd27c77c5bfcf734cec4f80f2125be568c523","Phir aaya Baloo bhaalu, Mowgli ka ustaad. Baloo ne jungle ke usool sikhaye. \"Hamesha sach bolo. Baron ki baat suno. Sab se meharbani karo.\" Mowgli ne dhyaan se suna."),
("c07ee0331d8a4095f9c0bfed3df306e1c1273ea567975da7c9ed4ccac56736ff","Ek din Bagheera ne kaha, \"Mowgli, bandaron ke saath mat jaana. Woh mazay ke liye cheezain chhupa lete hain, aur raasta bhool jaate hain.\" Mowgli ne sir hilaya. Magar kya woh yaad rakhega?"),
("f038bdfda52819a538dd6ba9a4834d5910f98b4626d94082f058d96ae9b37388","Dopahar ko Baloo so gaya. Darakht se bandaron ne aawaz di, \"Mowgli! Aao, meethe aam khao!\" Mowgli ko aam bohat pasand the. Woh Bagheera ki baat bhool gaya."),
("241d19dcd6a56b730b9264c5007a5e329c4222288ea0f574df29154367e383e5","Bandar Mowgli ka haath pakad kar darakhton par jhoolte gaye. Door, aur door! Woh usay purane patthar ke mehal mein le gaye. Mowgli ko pata hi nahi chala ke ghar kitna peeche reh gaya."),
("e08bdddefb57e1de41fea2adc3cccef5f52f3bf686cdb51bb14c72a7eade1816","Mehal mein bandar shor machate, chhilke phenkte, aur koi usool nahi maante. Mowgli ko ammi aur Baloo yaad aaye. Usne socha, \"Mujhe Bagheera ki baat maanni chahiye thi.\""),
("ebb3c9e42eb25322c4f024bd6cc416afcec1e72ed569f08ffd524bcee80c90a6","Mowgli ne himmat ki. Usne zor se aawaz di, \"Madad! Main yahan hoon!\" Ek pyaari cheel ne suna. \"Main tumhare doston ko bataati hoon,\" cheel boli, aur ud gayi."),
("e19ab3a01f3157b8f5d6d353be214ddb6cb11e2fd7811d8e842f4cedfcbb75e6","Baloo aur Bagheera ne Kaa saanp se madad maangi. \"Meharbani kar ke hamare Mowgli ko dhoondne mein madad karo,\" Baloo ne adab se kaha. Kaa muskuraya, \"Zaroor! Dost hi dost ke kaam aata hai.\""),
("304bde4df0e7b80b3852090cbca06d70bf8e9b80d42134415a666cb514b0377c","Kaa lambaa ho kar lehraya, aur bandar hanste hanste bhaag gaye. Mowgli daud kar apne doston ki taraf aaya. Baloo ne usay gale lagaya. Sab bohat khush the!"),
("5a37a51f70cd91feb6851eb6fa711d87730910394f3d4fbf2aa0199810491666","Mowgli ne sach bola, \"Main ne baat nahi maani thi. Mujhe maaf kar do.\" Baloo ne kaha, \"Sach bolna bahaduri hai.\" Phir Mowgli ne Kaa ka shukriya ada kiya."),
("b134ebfdfc065b6699cfeabd6697ef5431493bd1436646c3a126dfc21d330208","Jungle mein Shere Khan sher bhi rehta tha. Woh hamesha naraz aur akela rehta. Chhote jaanwar usse door bhaagte. Koi nahi jaanta tha ke woh itna naraz kyun hai."),
("9684308fec7b47b6746a389c3b9a3319227b4e24e1992e58952193791721d51a","Ek din Mowgli ne dekha ke Shere Khan ke panje mein kaanta chubha hai. Sab ghabra gaye, magar Mowgli ne himmat ki. Woh aahista aahista aage badha. \"Kya main madad kar sakta hoon?\" usne pyaar se poocha."),
("cb41ec191f74753575a520c01762ad5d6b99773cde922fc777f2a31e02732beb","Mowgli ne bohat aaram se kaanta nikaal diya. Shere Khan ne lambi saans li. \"Ab dard nahi ho raha!\" Woh hairan tha ke kisi ne uski itni madad ki."),
("092c4e233d5b4034441661e5c6f3c479d56804477bbd2b367cda9140dc5b8790","\"Shukriya, Mowgli,\" Shere Khan ne kaha. \"Main naraz tha kyun ke mujhe dard tha.\" Usne vaada kiya ke ab woh sab se pyaar se pesh aayega. Meharbani ne dushman ko dost bana diya."),
("e4da8993401264e45f6eaa494e346a09d36ce1ad6bfeb1ce71644639ce61f926","Ab sab jaanwar mil kar rehte the. Darya ke kinare picnic hui. Mowgli ne apne phal sab ke saath baante. Jo baant kar khaate hain, unki khushi bhi barh jaati hai."),
("61d5e0e3571156d0a64aa604401e25a73f93bda156cb4d22496ff1fcf5440cd4","Shaam ko Mowgli ne Ammi Bhediya se poocha, \"Mera asal ghar kahan hai?\" Ammi ne usay gale lagaya. \"Jahan tumse pyaar karne waale hain, wahi tumhara ghar hai.\" Mowgli muskuraya. Woh jaanta tha ke woh apne ghar mein hai."),
("0b4a2c80a3f95430fbcca39416b06eea02af955a196bac66378de716f649dcd4","Chaand nikla aur taare chamakne lage. Mowgli apne pyaare ghar waalon ke beech so gaya. Jungle mein sukoon tha. Shubh raat, Mowgli!"),
(None,"SABAQ"),
]
SABAQ=["Hamesha sach bolo, chahe ghalti apni ho.","Baron ki baat suno, woh hamari hifazat karte hain.","Himmat aur meharbani se dushman bhi dost ban jaate hain.","Doston ka shukriya ada karo, aur cheezain mil kar baanto."]
